import{C as n,o,c as i,j as t,a as s,E as d,a2 as l}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Start Reading","description":"Hearth documentation entry point: project introduction, reading paths, documentation structure, and current status.","frontmatter":{"title":"Start Reading","description":"Hearth documentation entry point: project introduction, reading paths, documentation structure, and current status.","outline":[2,3]},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md","lastUpdated":1793706118000}'),h={name:"en/guide/index.md"},g=Object.assign(h,{setup(c){const a=[{no:"01",title:"Understanding Hearth",text:"A one-sentence positioning, target users, product boundaries, and why it is not just another Codex.",link:"/en/guide/what-is-hearth"},{no:"02",title:"Reading Guide",text:"Three reading paths, the site map, and the documentation conventions.",link:"/en/guide/reading-guide"},{no:"03",title:"Project Status",text:"Currently in the specification phase; learn what has been completed, what has not started, and what comes next.",link:"/en/guide/project-status"}];return(u,e)=>{const r=n("DocCardGrid");return o(),i("div",null,[e[0]||(e[0]=t("p",{class:"eyebrow"},"START HERE",-1)),e[1]||(e[1]=t("h1",{id:"from-intent-to-reliable-tasks",tabindex:"-1"},[s("From Intent to Reliable Tasks "),t("a",{class:"header-anchor",href:"#from-intent-to-reliable-tasks","aria-label":'Permalink to "From Intent to Reliable Tasks"'},"​")],-1)),e[2]||(e[2]=t("p",{class:"lead"},'Hearth is a single-user, self-hosted, long-running personal Agent OS. The documentation site is organized as "product judgment → system design → delivery roadmap → reference appendix," helping you find the layer you need in the shortest time possible.',-1)),d(r,{items:a}),e[3]||(e[3]=l('<h2 id="the-bottom-line-first" tabindex="-1">The Bottom Line First <a class="header-anchor" href="#the-bottom-line-first" aria-label="Permalink to &quot;The Bottom Line First&quot;">​</a></h2><p>The core of Hearth is not &quot;building another model,&quot; but task control, durable execution, memory, verification, approval, receipts, and a quiet task card experience. It turns personal digital labor into an auditable, recoverable, and verifiable execution chain.</p><p>The roadmap rests on three core principles:</p><ol><li><strong>Build the minimal product first, then the complete OS.</strong> A daily-usable MVP must emerge within Stage 1 itself.</li><li><strong>The frontend exists from day one.</strong> Every increment must have a user-visible path, verification, and recovery.</li><li><strong>No calendar-based scheduling.</strong> Stages are capability gates, not schedule commitments.</li></ol><h2 id="three-reading-paths" tabindex="-1">Three Reading Paths <a class="header-anchor" href="#three-reading-paths" aria-label="Permalink to &quot;Three Reading Paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Who It&#39;s For</th><th>Suggested Order</th></tr></thead><tbody><tr><td>Product &amp; Decisions</td><td>Judging whether to continue investing, needing to understand scope and risks</td><td><a href="/hearth-os/en/product/definition.html">Product Definition</a> → <a href="/hearth-os/en/delivery/roadmap.html">Roadmap</a> → <a href="/hearth-os/en/delivery/development-plan.html">Development Plan</a> → <a href="/hearth-os/en/delivery/risks.html">Risks</a></td></tr><tr><td>Architecture &amp; Technology</td><td>Preparing to start implementation, needing to check system boundaries</td><td><a href="/hearth-os/en/architecture/">Architecture Overview</a> → <a href="/hearth-os/en/architecture/domain-model.html">Domain Protocol</a> → <a href="/hearth-os/en/architecture/control-plane.html">Control Plane</a> → <a href="/hearth-os/en/architecture/executor-model.html">Executor</a> → <a href="/hearth-os/en/architecture/evaluation.html">Evaluation</a></td></tr><tr><td>Start Building Directly</td><td>Already prepared to create the repository, needing to find the first vertical slice</td><td><a href="/hearth-os/en/delivery/stage-0.html">Stage 0</a> → <a href="/hearth-os/en/delivery/stage-1.html">Stage 1</a> → <a href="/hearth-os/en/architecture/durable-execution.html">Durable Execution</a> → <a href="/hearth-os/en/architecture/executor-catalog.html">Codex Executor</a></td></tr></tbody></table><h2 id="documentation-structure" tabindex="-1">Documentation Structure <a class="header-anchor" href="#documentation-structure" aria-label="Permalink to &quot;Documentation Structure&quot;">​</a></h2><ul><li><strong>Start</strong>: Project introduction, reading approach, and current status.</li><li><strong>Product</strong>: Definition, design principles, task coverage, and completion criteria.</li><li><strong>System Design</strong>: Overall architecture, domain model, control plane, executor, security, memory, evolution, Token economy, frontend, and evaluation.</li><li><strong>Delivery Roadmap</strong>: Stage 0–6, the development plan from 0 to 100, engineering structure, and risks.</li><li><strong>Reference</strong>: Build-vs-integrate boundaries, glossary, default checklist, FAQ, contribution guide, and the complete roadmap archive.</li></ul><p>The complete main document is preserved on the <a href="/hearth-os/en/reference/full-roadmap.html">archive page</a>. For daily reading, we recommend using the topic pages reorganized in this folder.</p>',9))])}}});export{p as __pageData,g as default};
